//! §16 — Justification & Verdicts (Decision Transparency).
//!
//! The Rust backend must NOT silently retry the 3-Strike loop. It returns a
//! structured `Verdict` object per strike, with the `reason` extracted
//! **deterministically** from the compiler/test output — never generated by
//! the LLM. This enforces Tier 2 (Fail Loudly) by making every failure and
//! hand-off to the Conductor transparent without wasting context tokens.

use serde::{Deserialize, Serialize};

/// The status of a single strike attempt inside the 3-strike loop.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "UPPERCASE")]
pub enum VerdictStatus {
    Passed,
    Failed,
    Timeout,
}

/// §16A — The Verdict payload. One per strike. Returned upward to the
/// Conductor so a frontend can render a clean, color-coded log entry
/// like:
///   `[STRIKE 2] FAILED: missing variable 'x' -> Retrying.`
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Verdict {
    /// 1-based attempt number.
    pub attempt: u8,
    /// PASSED | FAILED | TIMEOUT.
    pub status: VerdictStatus,
    /// Deterministic, single-line reason extracted from compiler output.
    /// NEVER generated by the LLM.
    pub reason: String,
    /// The next action the Conductor should surface, e.g.
    /// "Feeding stderr back to local LLM for Strike 3." or
    /// "Ok(String) returned upward — gate passed."
    pub action: String,
}

impl Verdict {
    pub fn passed(attempt: u8, action: impl Into<String>) -> Self {
        Self {
            attempt,
            status: VerdictStatus::Passed,
            reason: String::new(),
            action: action.into(),
        }
    }

    pub fn failed(attempt: u8, reason: impl Into<String>, action: impl Into<String>) -> Self {
        Self {
            attempt,
            status: VerdictStatus::Failed,
            reason: reason.into(),
            action: action.into(),
        }
    }

    pub fn timeout(attempt: u8, action: impl Into<String>) -> Self {
        Self {
            attempt,
            status: VerdictStatus::Timeout,
            reason: "Execution timed out".to_string(),
            action: action.into(),
        }
    }
}

/// §16A — Extract a single-line, deterministic reason from compiler/test
/// output. We do NOT ask the LLM to justify failures — we pull the first
/// salient error line straight from stderr.
///
/// Recognised patterns (in priority order):
///   - `error[EXXXX]:`        (Rust cargo)
///   - `error:`               (generic compiler: tsc, g++, clang)
///   - `Error:`               (Python, pytest)
///   - `FAIL` / `AssertionError` (pytest / unittest)
///   - `parse error` / `Parser error` (openscad)
///   - first non-empty line (fallback)
pub fn extract_reason(stderr: &str) -> String {
    if stderr.trim().is_empty() {
        return "gate produced no stderr".to_string();
    }
    // A failing test's panic says what actually went wrong; cargo's own
    // "error: test failed, to rerun pass `--test x`" line does not. Rust
    // prints the location line, then the message on the next line.
    let lines: Vec<&str> = stderr.lines().collect();
    if let Some(i) = lines.iter().position(|l| l.contains("panicked at")) {
        let msg = lines.get(i + 1).map(|l| l.trim()).filter(|l| !l.is_empty() && !l.starts_with("note:"));
        return truncate(&match msg {
            Some(m) => format!("{} {m}", lines[i].trim()),
            None => lines[i].trim().to_string(),
        });
    }
    // Python: the final exception line of a traceback is the reason (the
    // last one, so a chained "During handling of…" traceback reports what
    // finally escaped).
    if stderr.contains("Traceback (most recent call last):") {
        if let Some(exc) = lines.iter().rev().map(|l| l.trim()).find(|l| is_exception_line(l)) {
            return truncate(exc);
        }
    }
    for line in stderr.lines() {
        let l = line.trim();
        if l.is_empty() || is_cargo_summary(l) {
            continue;
        }
        // gcc / clang: "file.c:2:10: error: message" (and "fatal error:").
        if l.contains(": error:") || l.contains(": fatal error:") {
            return truncate(l);
        }
        // Node / Python style: "ReferenceError: x is not defined".
        if is_exception_line(l) {
            return truncate(l);
        }
        // Rust: error[E0425]: cannot find value `x` in this scope
        if l.starts_with("error[") || l.starts_with("error:") {
            return truncate(l);
        }
        // Generic compiler / Python.
        if l.starts_with("Error:") || l.starts_with("ERROR:") {
            return truncate(l);
        }
        // pytest / unittest failures.
        if l.contains("AssertionError") || l.contains("FAILED") || l.contains("FAIL") {
            return truncate(l);
        }
        // OpenSCAD parser errors.
        if l.contains("parse error") || l.contains("Parser error") || l.contains("CGAL") {
            return truncate(l);
        }
    }
    // Fallback: first non-empty line.
    stderr
        .lines()
        .find(|l| !l.trim().is_empty())
        .map(|l| truncate(l.trim()))
        .unwrap_or_else(|| "gate failed (no reason extracted)".to_string())
}

/// A line that *starts* with an exception type — an identifier ending in
/// `Error` or `Exception` (optionally dotted, e.g. `json.decoder.JSONDecodeError`)
/// followed by `: `. Prose that merely mentions "TypeError" does not count.
fn is_exception_line(l: &str) -> bool {
    let Some((name, _)) = l.split_once(": ") else {
        return false;
    };
    (name.ends_with("Error") || name.ends_with("Exception"))
        && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.')
        && name.chars().next().is_some_and(|c| c.is_ascii_alphabetic())
}

/// Cargo's closing lines say *that* something failed, not *what*. They are
/// only used as the reason when nothing more specific was printed.
fn is_cargo_summary(l: &str) -> bool {
    l.starts_with("error: test failed, to rerun")
        || l.starts_with("error: doctest failed, to rerun")
        || l.starts_with("error: could not compile")
        || l.starts_with("error: aborting due to")
}

/// Truncate to a UI-friendly single line (max 120 chars).
fn truncate(s: &str) -> String {
    let single = s.split('\n').next().unwrap_or(s);
    let mut out = single.trim().to_string();
    if out.chars().count() > 120 {
        // Cut on a word boundary near the limit.
        let cut: String = out.chars().take(117).collect();
        out = format!("{cut}…");
    }
    out
}

#[cfg(test)]
mod tests {
    //! Exhaustive unit tests for §16 verdict extraction + constructors.
    //!
    //! `extract_reason` is the deterministic justifier — it must NEVER ask
    //! the LLM. These tests pin every recognised error pattern + the
    //! fallback + the empty-stderr case + truncation.

    use super::*;

    // -------- extract_reason: Rust cargo patterns --------

    #[test]
    fn extract_rust_error_with_code() {
        let s = "error[E0425]: cannot find value `x` in this scope\n  --> src/main.rs:3:5";
        assert_eq!(extract_reason(s), "error[E0425]: cannot find value `x` in this scope");
    }

    #[test]
    fn extract_rust_error_without_code() {
        let s = "error: this file contains an unbalanced number of braces";
        assert_eq!(extract_reason(s), "error: this file contains an unbalanced number of braces");
    }

    // -------- extract_reason: generic compiler patterns --------

    #[test]
    fn extract_generic_error_lowercase() {
        let s = "error TS2304: Cannot find name 'foo'.\n  at line 5";
        assert!(extract_reason(s).starts_with("error TS2304"));
    }

    #[test]
    fn extract_python_error() {
        let s = "Error: division by zero\n  File \"main.py\", line 3";
        assert_eq!(extract_reason(s), "Error: division by zero");
    }

    #[test]
    fn extract_uppercase_error() {
        let s = "ERROR: something went wrong";
        assert_eq!(extract_reason(s), "ERROR: something went wrong");
    }

    // -------- extract_reason: pytest / unittest patterns --------

    #[test]
    fn extract_assertion_error() {
        let s = "    assert x == 3\nAssertionError: assert 2 == 3";
        let r = extract_reason(s);
        assert!(r.contains("AssertionError"));
    }

    #[test]
    fn extract_failed_marker() {
        let s = "FAILED tests/test_main.py::test_one - assert 1 == 2";
        let r = extract_reason(s);
        assert!(r.contains("FAILED"));
    }

    #[test]
    fn extract_fail_marker() {
        // "FAIL" is a substring of "FAILED" so the FAILED branch catches
        // both; this test pins the lower-priority FAIL marker on its own.
        let s = "FAIL: the test could not run";
        let r = extract_reason(s);
        assert!(r.contains("FAIL"));
    }

    // -------- extract_reason: OpenSCAD patterns --------

    #[test]
    fn extract_parse_error_lowercase() {
        let s = "parse error: unexpected token\n  line 5";
        let r = extract_reason(s);
        assert!(r.contains("parse error"));
    }

    #[test]
    fn extract_parser_error_capitalised() {
        let s = "Parser error: missing semicolon";
        let r = extract_reason(s);
        assert!(r.contains("Parser error"));
    }

    #[test]
    fn extract_cgal_error() {
        let s = "CGAL error: no top-level geometry produced";
        let r = extract_reason(s);
        assert!(r.contains("CGAL"));
    }

    // -------- extract_reason: edge cases --------

    #[test]
    fn extract_empty_stderr_returns_default() {
        assert_eq!(extract_reason(""), "gate produced no stderr");
    }

    #[test]
    fn extract_whitespace_only_stderr_returns_default() {
        assert_eq!(extract_reason("   \n\t\n  "), "gate produced no stderr");
    }

    #[test]
    fn extract_fallback_first_non_empty_line() {
        // No recognised pattern → first non-empty line wins.
        let s = "some random compiler message\nsecond line";
        assert_eq!(extract_reason(s), "some random compiler message");
    }

    #[test]
    fn extract_skips_blank_leading_lines() {
        let s = "\n\n\nactual error here";
        assert_eq!(extract_reason(s), "actual error here");
    }

    #[test]
    fn extract_trims_whitespace() {
        let s = "   error: leading spaces   ";
        assert_eq!(extract_reason(s), "error: leading spaces");
    }

    // -------- extract_reason: truncation --------

    #[test]
    fn extract_truncates_very_long_lines() {
        let long = format!("error: {}", "x".repeat(200));
        let r = extract_reason(&long);
        // Truncated to 117 chars + "…" = 118 total (char count).
        assert!(r.chars().count() <= 120);
        assert!(r.ends_with('…'));
    }

    #[test]
    fn extract_does_not_truncate_short_lines() {
        let s = "error: short";
        let r = extract_reason(s);
        assert_eq!(r, "error: short");
        assert!(!r.ends_with('…'));
    }

    #[test]
    fn extract_takes_only_first_line_of_multiline_match() {
        // A multiline "error:" block — only the first line is the reason.
        let s = "error: first\n  detail line\n  more detail";
        assert_eq!(extract_reason(s), "error: first");
    }

    // -------- extract_reason: priority ordering --------

    #[test]
    fn extract_rust_error_takes_priority_over_assertion() {
        // A stderr with both a rust error AND an assertion — the rust
        // error appears first and must win.
        let s = "error[E0425]: cannot find value `x`\nAssertionError: ...";
        assert!(extract_reason(s).starts_with("error[E0425]"));
    }

    // -------- Verdict constructors --------

    #[test]
    fn verdict_passed_has_empty_reason() {
        let v = Verdict::passed(1, "ok upward");
        assert_eq!(v.attempt, 1);
        assert_eq!(v.status, VerdictStatus::Passed);
        assert!(v.reason.is_empty());
        assert_eq!(v.action, "ok upward");
    }

    #[test]
    fn verdict_failed_carries_reason_and_action() {
        let v = Verdict::failed(2, "missing variable", "retry strike 3");
        assert_eq!(v.attempt, 2);
        assert_eq!(v.status, VerdictStatus::Failed);
        assert_eq!(v.reason, "missing variable");
        assert_eq!(v.action, "retry strike 3");
    }

    #[test]
    fn verdict_timeout_has_fixed_reason() {
        let v = Verdict::timeout(3, "kill child");
        assert_eq!(v.attempt, 3);
        assert_eq!(v.status, VerdictStatus::Timeout);
        assert_eq!(v.reason, "Execution timed out");
        assert_eq!(v.action, "kill child");
    }

    // -------- VerdictStatus serialisation --------

    #[test]
    fn verdict_status_serialises_uppercase() {
        // §16A payload requires "PASSED" | "FAILED" | "TIMEOUT".
        let s = serde_json::to_string(&VerdictStatus::Passed).unwrap();
        assert_eq!(s, "\"PASSED\"");
        let s = serde_json::to_string(&VerdictStatus::Failed).unwrap();
        assert_eq!(s, "\"FAILED\"");
        let s = serde_json::to_string(&VerdictStatus::Timeout).unwrap();
        assert_eq!(s, "\"TIMEOUT\"");
    }

    #[test]
    fn verdict_round_trips_through_json() {
        let v = Verdict::failed(2, "reason", "action");
        let j = serde_json::to_string(&v).unwrap();
        let back: Verdict = serde_json::from_str(&j).unwrap();
        assert_eq!(back.attempt, 2);
        assert_eq!(back.status, VerdictStatus::Failed);
        assert_eq!(back.reason, "reason");
        assert_eq!(back.action, "action");
    }

    #[test]
    fn cargo_test_failure_reports_the_panic_not_the_generic_line() {
        let out = "error: test failed, to rerun pass `--test hidden`\n--- stdout ---\nrunning 2 tests\n---- ok stdout ----\n\nthread 'ok' panicked at tests/hidden.rs:3:10:\nassertion `left == right` failed\n  left: 2\n right: 3\nnote: run with `RUST_BACKTRACE=1`\n";
        let r = extract_reason(out);
        assert!(r.contains("panicked at tests/hidden.rs:3:10") && r.contains("assertion `left == right` failed"), "{r}");
    }

    #[test]
    fn specific_compile_error_beats_cargo_summary_lines() {
        let out = "error: doctest failed, to rerun pass `--doc`\n--- stdout ---\nerror[E0425]: cannot find function `balanced` in this scope\n";
        assert!(extract_reason(out).starts_with("error[E0425]"), "{}", extract_reason(out));
    }

    #[test]
    fn cargo_summary_is_still_the_fallback() {
        assert!(extract_reason("error: could not compile `task`\n").contains("could not compile"));
    }

    // ---- captured from the real tools (python3, gcc, node, openscad) ----
    #[test] fn real_python_traceback_reports_the_exception() {
        let r = extract_reason(r####"Traceback (most recent call last):
  File "/home/user/work/fixtures/bad.py", line 4, in <module>
    parse("x1")
    ~~~~~^^^^^^
  File "/home/user/work/fixtures/bad.py", line 2, in parse
    return int(s)
ValueError: invalid literal for int() with base 10: 'x1'
"####);
        assert!(r.starts_with("ValueError: invalid literal for int()"), "{r}");
    }
    #[test] fn real_gcc_output_reports_the_error_line() {
        let r = extract_reason(r####"bad.c: In function ‘main’:
bad.c:2:10: error: ‘y’ undeclared (first use in this function)
    2 |   return y + 1;
      |          ^
bad.c:2:10: note: each undeclared identifier is reported only once for each function it appears in
"####);
        assert!(r.contains("error:") && r.contains("undeclared"), "{r}");
        assert!(!r.contains("In function"), "{r}");
    }
    #[test] fn real_node_stack_reports_the_error_not_the_path() {
        let r = extract_reason(r####"/home/user/work/fixtures/bad.js:1
function f() { return missingThing(); }
               ^

ReferenceError: missingThing is not defined
    at f (/home/user/work/fixtures/bad.js:1:16)
    at Object.<anonymous> (/home/user/work/fixtures/bad.js:2:1)
    at Module._compile (node:internal/modules/cjs/loader:1934:14)
    at Object..js (node:internal/modules/cjs/loader:2074:10)
    at Module.load (node:internal/modules/cjs/loader:1656:32)
    at Module._load (node:internal/modules/cjs/loader:1448:12)
    at wrapModuleLoad (node:internal/modules/cjs/loader:261:19)
    at Module.executeUserEntryPoint [as runMain] (node:internal/modules/run_main:154:5)
    at node:internal/main/run_main_module:33:47

Node.js v26.8.2
"####);
        assert!(r.starts_with("ReferenceError: missingThing is not defined"), "{r}");
    }
    #[test] fn real_openscad_parser_error() {
        let r = extract_reason(r####"ERROR: Parser error: syntax error in file bad.scad, line 3
Can't parse file 'bad.scad'!

"####);
        assert!(r.contains("Parser error"), "{r}");
    }
    #[test] fn javascript_error_type_in_prose_is_not_mistaken_for_an_error_line() {
        let r = extract_reason("note: see TypeError docs for details\nerror[E0308]: mismatched types\n");
        assert!(r.starts_with("error[E0308]"), "{r}");
    }

    #[test] fn chained_python_traceback_reports_the_final_exception() {
        let tb = "Traceback (most recent call last):\n  File \"a.py\", line 1\nKeyError: 'k'\n\nDuring handling of the above exception, another exception occurred:\n\nTraceback (most recent call last):\n  File \"a.py\", line 3\nRuntimeError: lookup failed\n";
        assert_eq!(extract_reason(tb), "RuntimeError: lookup failed");
    }
}
